SELECT CAST(COUNT(CASE WHEN p.drug_type = 'GLP‑1 receptor agonist' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 0 AND 11 THEN 1 END) AS FLOAT) / NULLIF(COUNT(CASE WHEN p.drug_type = 'GLP‑1 receptor agonist' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 23 AND 24 THEN 1 END), 0) AS proportion_first_twelve_hours, CAST(COUNT(CASE WHEN p.drug_type = 'GLP‑1 receptor agonist' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 23 AND 24 THEN 1 END) AS FLOAT) - NULLIF(COUNT(CASE WHEN p.drug_type = 'GLP‑1 receptor agonist' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 0 AND 11 THEN 1 END), 0) AS net_change FROM patients p JOIN chartevents c ON p.subject_id = c.subject_id WHERE p.gender = 'M' AND p.anchor_age = 53 AND EXTRACT(YEAR FROM c.charttime) = 2018 AND p.anchor_year = 2018 AND p.anchor_year_group = '48–58' AND d_icd_diagnoses.icd_code IN ('254643', '443493');